"""Checked circular-contact alternative for an intruding logical outline.

Keep the primary boundary, including all metadata, when it is valid. Only an
otherwise valid outline rejected by its complete internal-ribbon check may
try the existing circle endpoint of the fixed-radius contact family. The
alternative repeats the same outline checks; downstream mesh, profile and
final-footprint guards remain responsible for accepting the whole surface.
No source identity, solved coordinates, width or radius override is used.
"""
import hashlib

import bpy


PREFIX = 'Prochitecture Streets / Original logical boundary chains / Curved footprints v2'
CONTACT = 'Continuous fixed-radius local-to-circle contact family'
MARKER = 'st_checked_circle_contact_alternative'


def _circle_endpoint(original, cache):
    """Copy only ancestors of the contact-family argument; share other groups."""
    if original in cache:
        return cache[original]
    children = {}
    contacts = []
    for node in original.nodes:
        if node.type != 'GROUP' or not node.node_tree:
            continue
        if node.label == CONTACT:
            if 'Circle Weight' not in node.inputs:
                raise ValueError('Unknown fixed-radius contact interface')
            contacts.append(node.name)
        else:
            child, count = _circle_endpoint(node.node_tree, cache)
            if count:
                children[node.name] = (child, count)
    count = len(contacts) + sum(item[1] for item in children.values())
    if not count:
        result = original
    else:
        result = original.copy()
        key = hashlib.sha256(original.name.encode()).hexdigest()[:16]
        result.name = 'Prochitecture Streets / Checked circle endpoint v1 / '+key
        for name, (child, _) in children.items():
            result.nodes[name].node_tree = child
        for name in contacts:
            socket = result.nodes[name].inputs['Circle Weight']
            for link in tuple(socket.links):
                result.links.remove(link)
            socket.default_value = 1.
    cache[original] = result, count
    return result, count


def build(original, *, cache=None):
    """Wrap one saved or freshly built checked outline, preserving its interface."""
    if original.get(MARKER):
        return original
    if cache is not None and original in cache:
        return cache[original]
    if not original.name.startswith(PREFIX):
        raise ValueError('Expected an original logical outline with footprint guards')
    sockets = [s for s in original.interface.items_tree if s.item_type == 'SOCKET']
    outputs = {s.name for s in sockets if s.in_out == 'OUTPUT'}
    if not {'Valid', 'Footprints Checked', 'Footprint Status'} <= outputs:
        raise ValueError('Missing checked-outline outputs')
    alternative, count = _circle_endpoint(original, {})
    if count < 1:
        raise ValueError('No fixed-radius contact family in the checked outline')
    # Preserve socket identifiers as well as names/order. Existing callers bind
    # by identifier; a newly allocated interface can silently detach their
    # inputs when the original builder interleaved input and output sockets.
    tree = original.copy()
    tree.name = 'Prochitecture Streets / Checked logical contact choice v1'
    tree.nodes.clear()
    tree[MARKER] = 1
    tree['st_circle_contact_call_count'] = count
    tree['st_contact_choice_source'] = original
    inp = tree.nodes.new('NodeGroupInput')
    out = tree.nodes.new('NodeGroupOutput')
    primary = tree.nodes.new('GeometryNodeGroup'); primary.node_tree = original
    primary.label = 'Retain the complete valid original outline'
    circle = tree.nodes.new('GeometryNodeGroup'); circle.node_tree = alternative
    circle.label = 'Same radius and guards, existing circular-contact endpoint'
    for socket in sockets:
        if socket.in_out == 'INPUT':
            for node in (primary, circle):
                tree.links.new(inp.outputs[socket.name], node.inputs[socket.name])

    def switch(kind, condition, yes=None, no=None, label=''):
        node = tree.nodes.new('GeometryNodeSwitch'); node.input_type = kind; node.label = label
        tree.links.new(condition, node.inputs['Switch'])
        for key, value in (('True', yes), ('False', no)):
            if value is not None:
                tree.links.new(value, node.inputs[key])
            elif kind == 'BOOLEAN':
                node.inputs[key].default_value = False
        return node.outputs['Output']

    # Nested Boolean switches keep the alternative lazy for accepted outlines,
    # malformed inputs, bad joins and intersecting outline wires alike.
    eligible = switch('BOOLEAN', primary.outputs['Footprints Checked'], circle.outputs['Valid'])
    use_circle = switch('BOOLEAN', primary.outputs['Valid'], no=eligible,
                        label='Only replace an intruding outline with a fully checked alternative')
    for socket in sockets:
        if socket.in_out != 'OUTPUT':
            continue
        kind = {'NodeSocketGeometry': 'GEOMETRY', 'NodeSocketBool': 'BOOLEAN'}[socket.socket_type]
        value = switch(kind, use_circle, circle.outputs[socket.name], primary.outputs[socket.name])
        tree.links.new(value, out.inputs[socket.name])
    if cache is not None:
        cache[original] = tree
    return tree


def install_saved_boundaries(roots):
    """Replace checked-outline calls once, leaving the shared caller tree intact.

    This is an explicit candidate-library operation. Already wrapped subgraphs
    are not traversed, so repeated installation is a no-op, not nested retries.
    """
    visited = set(); calls = []; pending = list(roots)
    while pending:
        tree = pending.pop()
        if tree in visited or tree.get(MARKER):
            continue
        visited.add(tree)
        for node in tree.nodes:
            if node.type != 'GROUP' or not node.node_tree:
                continue
            if node.node_tree.name.startswith(PREFIX):
                calls.append(node)
            else:
                pending.append(node.node_tree)
    cache = {}
    for node in calls:
        node.node_tree = build(node.node_tree, cache=cache)
    return dict(replaced_calls=len(calls), shared_alternatives=len(cache),
                policy='Primary valid: unchanged. Footprint rejection: checked circular endpoint. Otherwise reject.')
